+++ 
@@ -1,1 +1,280 @@
-VAT/Editor/
\ No newline at end of file
+Shader "BillTheDev/VAT/ToonLit_VAT"
+{
+    Properties
+    {
+        [Header(Texture)]
+        _MainTex ("Albedo (RGB)", 2D) = "white" {}
+        _PositionTexture ("Position Texture (VAT)", 2D) = "white" {}
+        _PositionMin ("Position Min (Local Space)", Vector) = (0,0,0,0)
+        _PositionMax ("Position Max (Local Space)", Vector) = (0,0,0,0)
+
+        [Header(Toon Shading)]
+        _ToonRampSmoothing ("Toon Ramp Smoothing", Range(0.001, 0.5)) = 0.05
+        _ToonSteps ("Toon Steps (Cel Steps)", Range(1, 8)) = 3
+        _ShadowColor ("Shadow Color", Color) = (0.15, 0.1, 0.2, 1)
+        _LitColor ("Lit Tint", Color) = (1, 1, 1, 1)
+        _ShadowStrength ("Shadow Receive Strength", Range(0, 1)) = 0.8
+
+        [Header(Rim Light)]
+        _RimColor ("Rim Color", Color) = (1, 1, 1, 1)
+        _RimPower ("Rim Power (Fresnel)", Range(0.5, 12)) = 4
+        _RimIntensity ("Rim Intensity", Range(0, 5)) = 1.5
+        _RimThreshold ("Rim Step Threshold", Range(0, 1)) = 0.5
+
+        [Header(Emission Mask)]
+        _EmissionMask ("Emission Mask (R=Emissive)", 2D) = "black" {}
+        _EmissionColor ("Emission Color", Color) = (1, 1, 1, 1)
+        _EmissionIntensity ("Emission Intensity", Range(0, 5)) = 1
+    }
+
+    SubShader
+    {
+        Tags { "RenderType"="Opaque" "LightMode"="ForwardBase" }
+        LOD 200
+        Cull Back
+
+        Pass
+        {
+            Tags { "LightMode"="ForwardBase" }
+
+            HLSLPROGRAM
+            #pragma vertex vert
+            #pragma fragment frag
+            #pragma multi_compile_instancing
+            #pragma multi_compile_fwdbase    // Bật shadow receiving cho ForwardBase pass
+            #pragma target 3.5
+
+            #include "UnityCG.cginc"
+            #include "Lighting.cginc"
+            #include "AutoLight.cginc"       // Shadow macros
+
+            struct AppData
+            {
+                float4 vertex       : POSITION;
+                float2 uv           : TEXCOORD0;
+                float2 vertexIdUV   : TEXCOORD1; // UV1 chứa tọa độ U để xác định vertex (VAT)
+                float3 normal       : NORMAL;
+                UNITY_VERTEX_INPUT_INSTANCE_ID
+            };
+
+            struct VertexToFragment
+            {
+                float2 uv           : TEXCOORD0;
+                float4 pos          : SV_POSITION;
+                float3 worldNormal  : TEXCOORD1;
+                float3 worldPos     : TEXCOORD2;
+                float3 viewDir      : TEXCOORD3;
+                SHADOW_COORDS(4)                // Shadow coordinate
+                UNITY_VERTEX_INPUT_INSTANCE_ID
+            };
+
+            // ─────────────────── Textures ───────────────────
+            sampler2D _MainTex;
+            sampler2D _PositionTexture;
+            sampler2D _EmissionMask;
+            float4 _PositionMin;
+            float4 _PositionMax;
+
+            // ─────────────────── Toon Params ───────────────────
+            float _ToonRampSmoothing;
+            float _ToonSteps;
+            float4 _ShadowColor;
+            float4 _LitColor;
+            float _ShadowStrength;
+
+            // ─────────────────── Rim Params ───────────────────
+            float4 _RimColor;
+            float _RimPower;
+            float _RimIntensity;
+            float _RimThreshold;
+
+            // ─────────────────── Emission Params ───────────────────
+            float4 _EmissionColor;
+            float _EmissionIntensity;
+
+            // ─────────────────── VAT Instancing ───────────────────
+            UNITY_INSTANCING_BUFFER_START(PerInstance)
+                UNITY_DEFINE_INSTANCED_PROP(float, _CurrentAnimNormalizedTime)
+                UNITY_DEFINE_INSTANCED_PROP(float, _PreviousAnimNormalizedTime)
+                UNITY_DEFINE_INSTANCED_PROP(float, _AnimationBlendWeight)
+            UNITY_INSTANCING_BUFFER_END(PerInstance)
+
+            // ─────────────────── VAT Decode (giữ nguyên logic gốc) ───────────────────
+            float3 DecodeLocalPosition(float vertexU, float timeV)
+            {
+                float4 encodedPosition = tex2Dlod(_PositionTexture, float4(vertexU, timeV, 0, 0));
+                return lerp(_PositionMin.xyz, _PositionMax.xyz, encodedPosition.xyz);
+            }
+
+            // ─────────────────── Toon Ramp Function ───────────────────
+            // Chia NdotL thành các bậc cel-shading rõ ràng
+            float ToonRamp(float ndotl)
+            {
+                // Quantize thành steps (kiểu MinionsArt)
+                float stepped = floor(ndotl * _ToonSteps) / _ToonSteps;
+                // Smoothstep nhẹ ở ranh giới để tránh aliasing quá cứng
+                float smoothed = smoothstep(stepped - _ToonRampSmoothing, stepped + _ToonRampSmoothing, ndotl);
+                return smoothed;
+            }
+
+            // ─────────────────── Vertex Shader ───────────────────
+            VertexToFragment vert(AppData v)
+            {
+                VertexToFragment o;
+                UNITY_SETUP_INSTANCE_ID(v);
+                UNITY_TRANSFER_INSTANCE_ID(v, o);
+
+                // === VAT: Giải mã vị trí từ texture (giữ nguyên logic gốc) ===
+                float vertexU = v.vertexIdUV.x;
+                float currentAnimTime = UNITY_ACCESS_INSTANCED_PROP(PerInstance, _CurrentAnimNormalizedTime);
+                float blendWeight = UNITY_ACCESS_INSTANCED_PROP(PerInstance, _AnimationBlendWeight);
+
+                float3 localPosition = DecodeLocalPosition(vertexU, currentAnimTime);
+
+                if (blendWeight > 0.001)
+                {
+                    float previousAnimTime = UNITY_ACCESS_INSTANCED_PROP(PerInstance, _PreviousAnimNormalizedTime);
+                    float3 previousLocalPosition = DecodeLocalPosition(vertexU, previousAnimTime);
+                    localPosition = lerp(previousLocalPosition, localPosition, blendWeight);
+                }
+
+                // === Transform ===
+                float4 worldPosition = mul(unity_ObjectToWorld, float4(localPosition, 1.0));
+                o.pos = mul(UNITY_MATRIX_VP, worldPosition);
+                o.uv = v.uv;
+                o.worldPos = worldPosition.xyz;
+
+                // Normal → world space (VAT không thay đổi normal, dùng mesh normal gốc)
+                o.worldNormal = normalize(UnityObjectToWorldNormal(v.normal));
+
+                // View direction cho fresnel rim light
+                o.viewDir = normalize(_WorldSpaceCameraPos.xyz - worldPosition.xyz);
+
+                // Shadow coord
+                TRANSFER_SHADOW(o);
+
+                return o;
+            }
+
+            // ─────────────────── Fragment Shader ───────────────────
+            fixed4 frag(VertexToFragment i) : SV_Target
+            {
+                UNITY_SETUP_INSTANCE_ID(i);
+
+                // === Albedo ===
+                fixed4 albedo = tex2D(_MainTex, i.uv);
+
+                // === Light Direction (Main Directional Light) ===
+                float3 lightDir = normalize(_WorldSpaceLightPos0.xyz);
+                float3 normal = normalize(i.worldNormal);
+
+                // === NdotL → Toon Ramp ===
+                float ndotl = dot(normal, lightDir) * 0.5 + 0.5; // Half-Lambert cho mềm hơn
+                float toonRamp = ToonRamp(ndotl);
+
+                // === Shadow Attenuation (nhận shadow từ các object khác) ===
+                float shadow = SHADOW_ATTENUATION(i);
+                // Blend shadow vào toon ramp — shadow làm tối thêm vùng đã tối
+                float finalLight = toonRamp * lerp(1.0, shadow, _ShadowStrength);
+
+                // === Toon Color: lerp giữa shadow color và lit color ===
+                float3 toonColor = lerp(_ShadowColor.rgb, _LitColor.rgb * _LightColor0.rgb, finalLight);
+                float3 result = albedo.rgb * toonColor;
+
+                // === Rim Light (Fresnel — kiểu MinionsArt) ===
+                float fresnel = pow(1.0 - saturate(dot(normal, i.viewDir)), _RimPower);
+                // Chỉ hiện rim ở phía ánh sáng chiếu tới (dot normal với light direction)
+                float rimDot = saturate(dot(normal, lightDir));
+                // Step cutoff cho rim sắc nét kiểu toon
+                float rim = step(_RimThreshold, fresnel * rimDot) * _RimIntensity;
+                // Rim cũng bị shadow che
+                rim *= shadow;
+                result += rim * _RimColor.rgb * albedo.rgb;
+
+                // === Emission Mask (cho mắt sáng, hiệu ứng glow, v.v.) ===
+                float emissionMask = tex2D(_EmissionMask, i.uv).r;
+                result += emissionMask * albedo.rgb * _EmissionColor.rgb * _EmissionIntensity;
+
+                return fixed4(result, albedo.a);
+            }
+            ENDHLSL
+        }
+
+        // ─────────────────── Shadow Caster Pass ───────────────────
+        // Để boss/enemy đổ bóng lên môi trường
+        Pass
+        {
+            Tags { "LightMode"="ShadowCaster" }
+
+            HLSLPROGRAM
+            #pragma vertex vertShadow
+            #pragma fragment fragShadow
+            #pragma multi_compile_instancing
+            #pragma multi_compile_shadowcaster
+            #pragma target 3.5
+
+            #include "UnityCG.cginc"
+
+            sampler2D _PositionTexture;
+            float4 _PositionMin;
+            float4 _PositionMax;
+
+            UNITY_INSTANCING_BUFFER_START(PerInstance)
+                UNITY_DEFINE_INSTANCED_PROP(float, _CurrentAnimNormalizedTime)
+                UNITY_DEFINE_INSTANCED_PROP(float, _PreviousAnimNormalizedTime)
+                UNITY_DEFINE_INSTANCED_PROP(float, _AnimationBlendWeight)
+            UNITY_INSTANCING_BUFFER_END(PerInstance)
+
+            struct AppDataShadow
+            {
+                float4 vertex       : POSITION;
+                float2 vertexIdUV   : TEXCOORD1;
+                float3 normal       : NORMAL;
+                UNITY_VERTEX_INPUT_INSTANCE_ID
+            };
+
+            struct V2FShadow
+            {
+                V2F_SHADOW_CASTER;
+                UNITY_VERTEX_INPUT_INSTANCE_ID
+            };
+
+            float3 DecodeLocalPosition(float vertexU, float timeV)
+            {
+                float4 encodedPosition = tex2Dlod(_PositionTexture, float4(vertexU, timeV, 0, 0));
+                return lerp(_PositionMin.xyz, _PositionMax.xyz, encodedPosition.xyz);
+            }
+
+            V2FShadow vertShadow(AppDataShadow v)
+            {
+                V2FShadow o;
+                UNITY_SETUP_INSTANCE_ID(v);
+                UNITY_TRANSFER_INSTANCE_ID(v, o);
+
+                float vertexU = v.vertexIdUV.x;
+                float currentAnimTime = UNITY_ACCESS_INSTANCED_PROP(PerInstance, _CurrentAnimNormalizedTime);
+                float blendWeight = UNITY_ACCESS_INSTANCED_PROP(PerInstance, _AnimationBlendWeight);
+
+                float3 localPosition = DecodeLocalPosition(vertexU, currentAnimTime);
+
+                if (blendWeight > 0.001)
+                {
+                    float previousAnimTime = UNITY_ACCESS_INSTANCED_PROP(PerInstance, _PreviousAnimNormalizedTime);
+                    float3 previousLocalPosition = DecodeLocalPosition(vertexU, previousAnimTime);
+                    localPosition = lerp(previousLocalPosition, localPosition, blendWeight);
+                }
+
+                v.vertex = float4(localPosition, 1.0);
+                TRANSFER_SHADOW_CASTER_NORMALOFFSET(o);
+                return o;
+            }
+
+            float4 fragShadow(V2FShadow i) : SV_Target
+            {
+                SHADOW_CASTER_FRAGMENT(i);
+            }
+            ENDHLSL
+        }
+    }
+    FallBack "Mobile/VertexLit"
+}

